/
// OfferNoticeView.swift
// Blaklisted
//
// Created by Jyoti Mishra on 06/10/25.
//

import Foundation
import SwiftUI
import StoreKit
import Combine

/// Banner shown under the book cover whenever the book carries an automatic
/// promotion (`active_offer`): when the sale ends and whether a code is needed.
struct OfferNoticeView: View {

 // MARK: - Properties
 var activeOffer: ActiveOfferModel?

 /// Deep maroon used for the text, and the soft pink it sits on. Deliberately
 /// literal: `AppColors.interactDarkRed` is a bright alert red, too harsh here.
 private let offerTextColor = Color(red: 140 / 255, green: 24 / 255, blue: 28 / 255)
 private let offerBackgroundColor = Color(red: 244 / 255, green: 199 / 255, blue: 202 / 255)

 /// The banner is only shown for an offer that actually ends: with a null
 /// `end_date` there is nothing to count down to and no deadline to act on.
 private var offerEndText: String? {
 guard let offer = activeOffer, offer.hasEndDate else { return nil }
 guard let endDate = offer.endDate?.offerDisplayDate() else { return nil }
 return "\(AppString.kSaleEnds) \(endDate)"
 }

 /// Only shown when the offer applies automatically. An offer that needs a
 /// code says nothing here, so no empty line is left behind.
 private var couponText: String? {
 guard let code = activeOffer?.code, !code.isEmpty else {
 return AppString.kNoCouponNeeded
 }
 return nil
 }

 // MARK: - Body
 var body: some View {
 if let offerEndText = offerEndText {
 VStack(spacing: SizeOfElement.four) {
 HStack(spacing: SizeOfElement.six) {
 Image(systemName: "clock")
 .font(.system(size: SizeOfElement.sixteen, weight: .semibold))

 Text(offerEndText)
 .font(.custom(FontName.bold.rawValue, size: SizeOfElement.sixteen))
 }

 if let couponText = couponText {
 Text(couponText)
 .font(.custom(FontName.regular.rawValue, size: SizeOfElement.fifteen))
 }
 }
 .foregroundColor(offerTextColor)
 .multilineTextAlignment(.center)
 .padding(.horizontal, SizeOfElement.twonty)
 .padding(.vertical, SizeOfElement.twelve)
 .background(offerBackgroundColor)
 .cornerRadius(SizeOfElement.twelve)
 .padding(.top, SizeOfElement.ten)
 }
 }
}

// MARK: - CreditSaleRowView
/// Row advertising the running credit pack discount. Only rendered when the
/// active promotions API actually returned a discounted credit pack.
struct CreditSaleRowView: View {

 // MARK: - EnvironmentObject
 @EnvironmentObject var inAppPurchaseObserver: InAppPurchaseObserver

 // MARK: - State Properties
 @State private var creditPacks: [CreditPackModel] = AppManager.activeCreditPacks

 // MARK: - Callbacks
 var didTapOnCell: EmptyCompletion?

 /// First credit pack that actually carries a running discount.
 private var discountedPack: CreditPackModel? {
 return creditPacks.first(where: { $0.discountDetails != nil })
 }

 private var discount: CreditPackDiscountModel? {
 return discountedPack?.discountDetails
 }

 private var originalPriceText: String? {
 guard let pack = discountedPack else { return nil }
 if let pid = pack.productId, let str = inAppPurchaseObserver.iapObserver?.getPriceString(forProductID: pid), !str.isEmpty {
 return str
 }
 guard let original = pack.originalPrice else { return nil }
 return String(format: "%@%.2f", AppManager.productLocale, original)
 }

 private var discountedPriceText: String? {
 guard let discount = discount else { return nil }
 if let discPid = discount.discountedProductId, let str = inAppPurchaseObserver.iapObserver?.getPriceString(forProductID: discPid), !str.isEmpty {
 return str
 }
 guard let discounted = discount.discountedPrice else { return nil }
 return String(format: "%@%.2f", AppManager.productLocale, discounted)
 }

 private var productsPublisher: AnyPublisher<[SKProduct], Never> {
 inAppPurchaseObserver.iapObserver?
 .$products
 .receive(on: RunLoop.main)
 .eraseToAnyPublisher()
 ?? Just([]).eraseToAnyPublisher()
 }

 private var dynamicTitle: String {
 guard let pack = discountedPack, let discount = pack.discountDetails else {
 return "Credit Sale"
 }

 let origProductId = pack.productId ?? AppString.kCredit01
 let discProductId = discount.discountedProductId

 var origPrice: Double? = nil
 var discPrice: Double? = nil

 if let origProduct = inAppPurchaseObserver.iapObserver?.getProduct(withID: origProductId) ?? AppManager.products.first(where: { $0.productIdentifier == origProductId }) {
 origPrice = origProduct.price.doubleValue
 }
 if let discPid = discProductId, let discProduct = inAppPurchaseObserver.iapObserver?.getProduct(withID: discPid) ?? AppManager.products.first(where: { $0.productIdentifier == discPid }) {
 discPrice = discProduct.price.doubleValue
 }

 if origPrice == nil {
 origPrice = pack.originalPrice
 }
 if discPrice == nil {
 discPrice = discount.discountedPrice
 }

 if let orig = origPrice, let disc = discPrice, orig > 0, disc < orig {
 let percentage = Int(round(((orig - disc) / orig) * 100.0))
 if percentage > 0 {
 return "Credit Sale \(percentage)%"
 }
 }

 if let name = discount.name, !name.isEmpty {
 return name
 }
 return "Credit Sale"
 }

 // MARK: - Body
 var body: some View {
 Group {
 if discount != nil, let discountedPriceText = discountedPriceText {
 Button {
 didTapOnCell?()
 } label: {
 HStack(spacing: SizeOfElement.eight) {
 Text(dynamicTitle)
 .modifier(AppFonts(fontName: .bold, size: SizeOfElement.fourteen, forgroundColor: AppColors.interactPrimary))
 .lineLimit(1)

 Spacer()

 if let originalPriceText = originalPriceText {
 Text(originalPriceText)
 .font(.system(size: 13, weight: .regular))
 .foregroundColor(Color(AppColors.textSecondary))
 .strikethrough(true, color: Color(AppColors.textSecondary))
 }

 Text(discountedPriceText)
 .font(.system(size: 14, weight: .bold))
 .foregroundColor(Color(AppColors.interactPrimary))

 Image(systemName: "chevron.right")
 .font(.system(size: SizeOfElement.twelve, weight: .semibold))
 .foregroundColor(Color(AppColors.interactPrimary))
 }
 .padding(.horizontal, SizeOfElement.fourteen)
 .frame(width: UIScreen.main.bounds.width - SizeOfElement.thirtyTwo, height: SizeOfElement.fourtyEight)
 .background(Color(AppColors.interactPrimary).opacity(0.08))
 .cornerRadius(SizeOfElement.six)
 }
 }
 }
 .onAppear {
 loadCreditPacks()
 }
 .onReceive(productsPublisher) { _ in }
 }

 // MARK: - Helper Methods
 private func loadCreditPacks() {
 if !AppManager.activeCreditPacks.isEmpty {
 creditPacks = AppManager.activeCreditPacks
 registerProducts(packs: creditPacks)
 return
 }

 BooksRepo().apiGetActiveOfferPromotions { data, _ in
 AppManager.activeSitewidePromotion = data?.sitewide
 AppManager.rebuildPromoBooksMap(from: data?.curatedTitles)
 guard let packs = data?.creditPack else { return }
 AppManager.activeCreditPacks = packs
 creditPacks = packs
 registerProducts(packs: packs)
 }
 }

 /// Makes sure StoreKit knows about the products so localised prices show up.
 /// Registered in one batch so a single request covers every id.
 private func registerProducts(packs: [CreditPackModel]) {
 var productIds = Set<String>()
 for pack in packs {
 if let pid = pack.productId, !pid.isEmpty {
 productIds.insert(pid)
 }
 if let discPid = pack.discountDetails?.discountedProductId, !discPid.isEmpty {
 productIds.insert(discPid)
 }
 }
 inAppPurchaseObserver.addNewProductIdsIfNeeded(productIds)
 }
}

// MARK: - Offer Date Formatting
extension String {
 /// Converts an ISO-8601 promotion date into the banner format, e.g. "Oct 07, 2026".
 func offerDisplayDate() -> String? {
 let inputFormatter = DateFormatter()
 inputFormatter.locale = Locale(identifier: "en_US_POSIX")
 inputFormatter.timeZone = TimeZone(identifier: "UTC")

 let formats = ["yyyy-MM-dd'T'HH:mm:ss.SSSZ", "yyyy-MM-dd'T'HH:mm:ssZ", "yyyy-MM-dd"]
 for format in formats {
 inputFormatter.dateFormat = format
 if let date = inputFormatter.date(from: self) {
 let outputFormatter = DateFormatter()
 outputFormatter.locale = Locale(identifier: "en_US_POSIX")
 outputFormatter.dateFormat = "MMM dd, yyyy"
 return outputFormatter.string(from: date)
 }
 }
 return nil
 }
}

